"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { getOfflineScans } from "@/lib/offline-db";
import { ScanEntry } from "@/types/menu";

// Prerender-disabled: requires active session
export const dynamic = "force-dynamic";

export default function HistoryPage() {
  const { status } = useSession();
  const router = useRouter();
  const [scans, setScans] = useState<ScanEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [isOffline, setIsOffline] = useState(false);
  const [selectedScans, setSelectedScans] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setIsOffline(!navigator.onLine);
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  useEffect(() => {
    if (status === "unauthenticated") {
      router.push("/auth/login");
    }
  }, [status, router]);

  useEffect(() => {
    const fetchScans = async () => {
      try {
        if (isOffline) {
          const offlineScans = await getOfflineScans();
          setScans(offlineScans);
          setTotalPages(1);
          return;
        }

        const res = await fetch(`/api/scans?page=${page}&limit=20`);
        if (!res.ok) throw new Error("Failed to fetch scans");
        const data = await res.json();
        setScans(data.scans || []);
        setTotalPages(data.total_pages || 1);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load history");
      } finally {
        setLoading(false);
      }
    };

    if (status === "authenticated") {
      fetchScans();
    }
  }, [status, page, isOffline]);

  const toggleScanSelection = (scanId: string) => {
    setSelectedScans((prev) => {
      if (prev.includes(scanId)) {
        return prev.filter((id) => id !== scanId);
      }
      if (prev.length >= 2) {
        return [prev[1], scanId];
      }
      return [...prev, scanId];
    });
  };

  const handleCompare = () => {
    if (selectedScans.length === 2) {
      router.push(`/compare?scanId1=${selectedScans[0]}&scanId2=${selectedScans[1]}`);
    }
  };

  const handleClearSelection = () => {
    setSelectedScans([]);
  };

  if (status === "loading" || loading) {
    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b">
          <div className="container mx-auto px-4 py-4 flex items-center justify-between">
            <h1 className="text-2xl font-bold">Scan History</h1>
            <Button variant="ghost" onClick={() => router.push("/")}>
              Home
            </Button>
          </div>
        </header>
        <main className="flex-1 container mx-auto px-4 py-8 max-w-2xl">
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <Card key={i} className="p-4">
                <Skeleton className="h-5 w-3/4 mb-2" />
                <Skeleton className="h-4 w-1/2" />
              </Card>
            ))}
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <header className="border-b">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">Scan History</h1>
            {selectedScans.length > 0 && (
              <p className="text-sm text-muted-foreground">
                {selectedScans.length} scan{selectedScans.length > 1 ? "s" : ""} selected
              </p>
            )}
          </div>
          <nav className="flex gap-2">
            {selectedScans.length > 0 && (
              <>
                <Button variant="outline" size="sm" onClick={handleClearSelection}>
                  Clear
                </Button>
                <Button
                  size="sm"
                  onClick={handleCompare}
                  disabled={selectedScans.length !== 2}
                >
                  Compare
                </Button>
              </>
            )}
            <Button variant="ghost" onClick={() => router.push("/scan")}>
              New Scan
            </Button>
            <Button variant="ghost" onClick={() => router.push("/")}>
              Home
            </Button>
          </nav>
        </div>
      </header>

      <main className="flex-1 container mx-auto px-4 py-8 max-w-2xl">
        {isOffline && (
          <div className="mb-4 p-3 rounded-md bg-yellow-500/10 text-yellow-700 text-sm">
            You&apos;re offline — showing cached scan history
          </div>
        )}
        <div className="space-y-4">
            {error && (
            <Card className="p-6 text-center space-y-4 border-destructive">
              <div className="text-5xl">Error</div>
              <h3 className="text-xl font-semibold">Failed to Load History</h3>
              <p className="text-muted-foreground">{error}</p>
              <Button onClick={() => { setError(null); setLoading(true); window.location.reload(); }}>Try Again</Button>
            </Card>
          )}
          {!error && scans.length > 0 ? (
            <>
              {scans.map((scan) => {
                const isSelected = selectedScans.includes(scan.id);
                return (
                  <Card
                    key={scan.id}
                    className={`p-4 transition-colors ${
                      isSelected ? "ring-2 ring-primary" : "hover:bg-accent"
                    }`}
                  >
                    <div className="flex items-start justify-between gap-4" onClick={() => {
                      if (!isOffline) {
                        toggleScanSelection(scan.id);
                      }
                    }}>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <Badge
                            variant={
                              scan.status === "completed"
                                ? "default"
                                : scan.status === "failed"
                                  ? "destructive"
                                  : "secondary"
                            }
                          >
                            {scan.status}
                          </Badge>
                          <span className="text-sm text-muted-foreground">
                            {scan.items_count} dishes
                          </span>
                          {isSelected && (
                            <Badge variant="outline" className="text-xs">
                              Selected
                            </Badge>
                          )}
                        </div>
                        {scan.agent_summary && (
                          <p className="text-sm text-muted-foreground line-clamp-2 mt-1">
                            {scan.agent_summary}
                          </p>
                        )}
                        {scan.dishes && scan.dishes.length > 0 && (
                          <div className="flex gap-1 mt-2">
                            {scan.dishes.map((dish, i) => (
                              <span key={i} className="text-xs bg-muted px-2 py-1 rounded">
                                {dish.name}
                              </span>
                            ))}
                          </div>
                        )}
                        <p className="text-xs text-muted-foreground mt-2">
                          {new Date(scan.created_at).toLocaleString()}
                        </p>
                      </div>
                      <div className="flex flex-col items-end gap-2 shrink-0">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={(e) => {
                            e.stopPropagation();
                            router.push(`/results/${scan.id}`);
                          }}
                        >
                          View
                        </Button>
                        <span className="text-xs text-muted-foreground">
                          {isOffline ? "Offline" : "Click to select"}
                        </span>
                      </div>
                    </div>
                  </Card>
                );
              })}
              {totalPages > 1 && !isOffline && (
                <div className="flex justify-center gap-2 pt-4">
                  <Button
                    variant="outline"
                    disabled={page <= 1}
                    onClick={() => setPage((p) => p - 1)}
                  >
                    Previous
                  </Button>
                  <span className="text-sm text-muted-foreground self-center">
                    Page {page} of {totalPages}
                  </span>
                  <Button
                    variant="outline"
                    disabled={page >= totalPages}
                    onClick={() => setPage((p) => p + 1)}
                  >
                    Next
                  </Button>
                </div>
              )}
            </>
          ) : (
            <Card className="p-8 text-center space-y-4">
              <div className="text-5xl">📋</div>
              <h3 className="text-xl font-semibold">No scans yet</h3>
              <p className="text-muted-foreground">
                Scan your first menu to see history here.
              </p>
              <Button onClick={() => router.push("/scan")}>Scan a Menu</Button>
            </Card>
          )}
        </div>
      </main>
    </div>
  );
}
